import unittest
from unittest.mock import patch, MagicMock
from backend.integrations.vendor_api_clients import *

class TestCrowdStrikeClient(unittest.TestCase):
    def setUp(self):
        self.client = CrowdStrikeClient("dummy_key", "https://api.crowdstrike.com")

    @patch("requests.post")
    def test_get_alerts_success(self, mock_post):
        """Test successful API call."""
        mock_resp = MagicMock()
        mock_resp.json.return_value = {"status": "success"}
        mock_post.return_value = mock_resp
        result = self.client.get_alerts("tgt-123", {"force": True})
        self.assertEqual(result["status"], "success")
        mock_post.assert_called_once()

    @patch("requests.post")
    def test_get_alerts_failure(self, mock_post):
        """Test failed API call."""
        mock_post.side_effect = requests.exceptions.RequestException("API Timeout")
        result = self.client.get_alerts("tgt-123")
        self.assertEqual(result["status"], "error")
        self.assertEqual(result["message"], "API Timeout")

